package com.eventhub.service; import com.eventhub.dto.AuditLogResponse; import com.eventhub.entity.AuditLog; import com.eventhub.repository.AuditLogRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor public class AuditLogService {private final AuditLogRepository repo; @Transactional(propagation=org.springframework.transaction.annotation.Propagation.REQUIRES_NEW) public void log(com.eventhub.entity.User user,String action,String type,Long id,String ip,String details){repo.save(AuditLog.builder().userId(user==null?null:user.getId()).action(action).entityType(type).entityId(id).ipAddress(ip).details(details).build());} @Transactional(readOnly=true) public Page<AuditLogResponse> list(String action,int page,int size){Pageable p=PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100));return (action==null||action.isBlank()?repo.findAllByOrderByTimestampDesc(p):repo.findByActionContainingIgnoreCaseOrderByTimestampDesc(action,p)).map(AuditLogResponse::from);}}
